export type searchResponse200 = {
  data: CollectionResponse
  status: 200
}

export type searchResponse400 = {
  data: ProblemResponse
  status: 400
}

export type searchResponse401 = {
  data: ProblemResponse
  status: 401
}

export type searchResponseSuccess = searchResponse200 & {
  headers: Headers
}
export type searchResponseError = (searchResponse400 | searchResponse401) & {
  headers: Headers
}

export type searchResponse = searchResponseSuccess | searchResponseError

export const getSearchUrl = (params: SearchParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/api/v1/search?${stringifiedParams}`
    : `/api/v1/search`
}

/**
 * @summary Search authorized content
 */
export const search = async (
  params: SearchParams,
  options?: RequestInit,
): Promise<searchResponse> => {
  const res = await fetch(getSearchUrl(params), {
    ...options,
    method: 'GET',
  })

  const body = [204, 205, 304].includes(res.status) ? null : await res.text()

  const data: searchResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as searchResponse
}

